public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;            // total possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;           // to keep only k bits
    int val = 0;
    // Build the value for the first window of length k
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    // Slide the window across the string
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            if (++count == total) return true;  // all codes found
        }
    }
    return false;  // not all codes occurred
}

