public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);

        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }

    int maxAbs = Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
    return maxAbs;
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1); // F1
    fibs.add(1); // F2
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // Greedy selection from largest to smallest
    int remaining = k;
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    java.util.List<Integer> bigFactors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int paired = n / i;
            if (paired != i) {
                bigFactors.add(paired);
            }
        }
    }
    for (int i = bigFactors.size() - 1; i >= 0; i--) {
        factors.add(bigFactors.get(i));
    }
    return k > factors.size() ? -1 : factors.get(k - 1);
}

