private int dfs(String s, int idx, java.util.Set<String> seen) {
    if (idx == s.length()) {
        return 0;
    }
    int max = 0;
    for (int j = idx + 1; j <= s.length(); j++) {
        String part = s.substring(idx, j);
        if (!seen.contains(part)) {
            seen.add(part);
            int candidate = 1 + dfs(s, j, seen);
            if (candidate > max) {
                max = candidate;
            }
            seen.remove(part);
        }
    }
    return max;
}

