public static List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    java.util.Queue<Long> q = new java.util.LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        q.offer((long) i);
    }
    while (!q.isEmpty()) {
        long curr = q.poll();
        if (curr > high) continue;
        if (curr >= low) result.add((int) curr);
        if (curr == 0) continue;
        long last = curr % 10;
        if (last > 0) {
            long next = curr * 10 + (last - 1);
            if (next <= high) q.offer(next);
        }
        if (last < 9) {
            long next = curr * 10 + (last + 1);
            if (next <= high) q.offer(next);
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long high = n / (factor * 10);
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + lower + 1;
        } else {
            count += (high + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

